static void appearance_texture112(Appearance58 selected,unsigned sex){unsigned key=appearance_thumb112(sex,selected.hair,selected.colour);if(appearanceTexture112&&appearanceKey112==key)return;static unsigned short atlas[256*160];unsigned short tile[32*32];int refresh=!appearanceTexture112||appearanceKey112==~0u||appearanceKey112/378!=sex||appearanceKey112%9!=selected.colour;if(refresh)memset(atlas,0,sizeof(atlas));for(unsigned i=refresh?0:42;i<51;i++){unsigned style=i<42?i:selected.hair,colour=i<42?selected.colour:i-42;appearance_decode_tile112(appearance_thumb112(sex,style,colour),tile);unsigned x=i%10*24,y=i/10*24;for(unsigned yy=0;yy<24;yy++)for(unsigned xx=0;xx<24;xx++)atlas[(y+yy)*256+x+xx]=tile[(yy*32/24)*32+xx*32/24];}while(pb_busy()){}if(!appearanceTexture112)appearanceTexture112=gpu_alloc(sizeof(atlas));memcpy(appearanceTexture112,atlas,sizeof(atlas));appearanceKey112=key;}
static void appearance_panels112(Appearance58 a,const AppearancePicker112*p,int focused){ui_panel(hairPanel112.x,hairPanel112.y,hairPanel112.w,hairPanel112.h,"Hair style",focused==8,-1);ui_panel(colourPanel112.x,colourPanel112.y,colourPanel112.w,colourPanel112.h,"Hair colour",focused==9,-1);for(unsigned mode=1;mode<=2;mode++)for(unsigned i=0;i<(mode==1?42u:9u);i++){FrontRect112 r=appearance_cell112(mode,i);pb_fill(r.x,r.y,r.w,r.h,0xffeaf0f5);ui_outline(r.x,r.y,r.w,r.h,0xff8999b2);int chosen=i==(mode==1?a.hair:a.colour);if(chosen)ui_outline(r.x,r.y,r.w,r.h,p->mode==mode?0xffffda45:0xff58aaff);}ui_hint64(231,287,.7f,p->mode==1?"D-pad: preview  A: keep  B: undo":"A / Right: choose a hairstyle");ui_hint64(231,373,.65f,p->mode==2?"Left/right: preview  A: keep  B: undo":"A / Right: choose a colour");}
static void appearance_thumbnails112(Appearance58 a,unsigned sex){appearance_texture112(a,sex);hud_setup_direct(appearanceTexture112,256,160,512,0x0001102a,1);for(unsigned i=0;i<51;i++){unsigned mode=i<42?1:2,index=i<42?i:i-42;FrontRect112 r=appearance_cell112(mode,index);hud_quad(r.x+2,r.y+2,r.w-4,r.h-4,(i%10)*24,(i/10)*24,24,24);}}
